"use strict";(self.rspackChunkvext_website=self.rspackChunkvext_website||[]).push([[4197],{3845(e,t,s){s.r(t);var n=s(4848),i=s(8453);function a(e){let t={a:"a",h1:"h1",h3:"h3",p:"p",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsxs)(t.h1,{id:"scheduled-jobs-contract",children:[(0,n.jsx)(t.a,{className:"rp-header-anchor","aria-hidden":"true",href:"#scheduled-jobs-contract",children:"#"}),"Scheduled Jobs contract"]}),"\n",(0,n.jsxs)(t.p,{children:["This page defines observable guarantees, prerequisites and limits. Use the ",(0,n.jsx)(t.a,{href:"/guide/jobs.html",children:"guide"})," for integration and the ",(0,n.jsx)(t.a,{href:"/api/jobs.html",children:"API"})," for precise fields."]}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.a,{id:"vext-job-001"})}),"\n",(0,n.jsxs)(t.h3,{id:"vext-job-001-must-application-startup",children:[(0,n.jsx)(t.a,{className:"rp-header-anchor","aria-hidden":"true",href:"#vext-job-001-must-application-startup",children:"#"}),"VEXT-JOB-001 [MUST] Application startup"]}),"\n",(0,n.jsx)(t.p,{children:"Startup validates configuration, names, Cron, timezone, declarations and necessary Redis connectivity. With enabled Jobs, necessary onReady failure rejects and cleans up startup; otherwise existing logged isolation remains. Observational app:ready notifications are separate from necessary initialization. Local activates after necessary readiness."}),"\n",(0,n.jsx)(t.p,{children:"In every built-in Cluster mode, Master completes Worker startup attempts and checks the actual ready-set manifests. A Worker registers future timers only on valid activation, then acknowledges. Master reports overall Jobs readiness after valid acknowledgements and a membership recheck. An activated Worker may schedule earlier; there is no second global release after all ACKs. Later coordination failure cannot roll back existing effects. Unactivated, stopped or timed-out Workers cannot regain eligibility through delayed messages. Partial startup failures follow existing capacity policy and are excluded from the ready set; no valid Worker means no startup success."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.a,{id:"vext-job-002"})}),"\n",(0,n.jsxs)(t.h3,{id:"vext-job-002-must-schedule-definitions",children:[(0,n.jsx)(t.a,{className:"rp-header-anchor","aria-hidden":"true",href:"#vext-job-002-must-schedule-definitions",children:"#"}),"VEXT-JOB-002 [MUST] Schedule definitions"]}),"\n",(0,n.jsx)(t.p,{children:"Every definition explicitly supplies a valid five/six/seven-field Cron or supported macro, rejecting interval, Date and one-off ISO dates. Timezone is task > jobs.timezone > UTC. Day/weekday defaults to OR, explicit +weekday means AND; calendar extensions and DST follow the installed Croner."}),"\n",(0,n.jsx)(t.p,{children:"Tasks default to enabled. Disabled definitions still validate fields, declarations, TTL and names but need no future point. Global disable skips discovery, not config validation. Enabled tasks need strictly future points at preparation and activation; finite-year plans stop normally after their last point."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.a,{id:"vext-job-003"})}),"\n",(0,n.jsxs)(t.h3,{id:"vext-job-003-must-execution-and-overlap",children:[(0,n.jsx)(t.a,{className:"rp-header-anchor","aria-hidden":"true",href:"#vext-job-003-must-execution-and-overlap",children:"#"}),"VEXT-JOB-003 [MUST] Execution and overlap"]}),"\n",(0,n.jsx)(t.p,{children:"Startup, restart and recovery select strictly future points without immediate execution or catch-up. An armed point delivered within its window may run; a cross-period delay is skipped. Repeated, old and locally busy points are never queued for replay."}),"\n",(0,n.jsx)(t.p,{children:"Same-name tasks skip overlap; different tasks may run concurrently. Handler errors are logged, with future periods and HTTP service continuing. Return values are not persisted. Logs distinguish planned/actual times, duration, mode, PID/Worker, outcomes and skip reasons; nextRunAt is diagnostic, never a successful-execution promise."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.a,{id:"vext-job-004"})}),"\n",(0,n.jsxs)(t.h3,{id:"vext-job-004-must-replica-configuration",children:[(0,n.jsx)(t.a,{className:"rp-header-anchor","aria-hidden":"true",href:"#vext-job-004-must-replica-configuration",children:"#"}),"VEXT-JOB-004 [MUST] Replica configuration"]}),"\n",(0,n.jsx)(t.p,{children:"Without jobs.redis, one application coordinates locally and one trusted built-in Cluster uses IPC within the current Master's Workers, without Redis. Ordinary environment flags or cluster.isWorker do not confer built-in authority. A failed trusted connection in declared built-in mode refuses admission without Local fallback."}),"\n",(0,n.jsx)(t.p,{children:"Independent applications, PM2 processes, containers or hosts cannot discover each other automatically. Explicitly share a Redis target, effective prefix and consistent definitions when they need coordination. Only a jobs.redis object enables Redis; an environment URL alone does not. All built-in modes check initial ready-set effective names, switches, Cron, timezones, mode and critical configuration. Redis adds known target, prefix and TTL; documentation metadata is excluded. A supplied opaque client's real target and consistency between independent applications remain deployment responsibilities. Empty/all-disabled sets create no unnecessary timers, Jobs Redis connections or extra task channels."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.a,{id:"vext-job-005"})}),"\n",(0,n.jsxs)(t.h3,{id:"vext-job-005-must-trigger-deduplication",children:[(0,n.jsx)(t.a,{className:"rp-header-anchor","aria-hidden":"true",href:"#vext-job-005-must-trigger-deduplication",children:"#"}),"VEXT-JOB-005 [MUST] Trigger deduplication"]}),"\n",(0,n.jsx)(t.p,{children:"Within a healthy domain, a same-name task receives at most one execution qualification per scheduled point. Quick completion, lease expiry or process crash does not make a consumed point reclaimable. Lost responses and late/expired permits cannot duplicate or revive admission. Sending a permission message does not prove business completion; Workers lacking valid permission do not run."}),"\n",(0,n.jsx)(t.p,{children:"A crash between qualification and business completion can lose an occurrence. This is scheduling deduplication, not guaranteed business success once. Partitions, Redis state loss and ignored cancellation require idempotency for side effects."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.a,{id:"vext-job-006"})}),"\n",(0,n.jsxs)(t.h3,{id:"vext-job-006-must-running-leases",children:[(0,n.jsx)(t.a,{className:"rp-header-anchor","aria-hidden":"true",href:"#vext-job-006-must-running-leases",children:"#"}),"VEXT-JOB-006 [MUST] Running leases"]}),"\n",(0,n.jsx)(t.p,{children:"Effective Redis TTL is Job.leaseTtl > jobs.redis.leaseTtl > 30000 milliseconds, a safe integer at least 1000, consistent for a task across replicas. Local/IPC validates the field without using Redis TTL. TTL does not change identity."}),"\n",(0,n.jsx)(t.p,{children:"Execution renews using that task's TTL; it is not a business timeout and long handlers may exceed it. Renewal/release acts only on its owner. Ordinary shutdown/rolling drain maintains in-flight leases until settlement or the shared deadline. Jobs closes URL-owned connections; callers close supplied clients. Redis Cluster task keys share a hash slot."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.a,{id:"vext-job-007"})}),"\n",(0,n.jsxs)(t.h3,{id:"vext-job-007-must-redis-failures",children:[(0,n.jsx)(t.a,{className:"rp-header-anchor","aria-hidden":"true",href:"#vext-job-007-must-redis-failures",children:"#"}),"VEXT-JOB-007 [MUST] Redis failures"]}),"\n",(0,n.jsx)(t.p,{children:"Unavailable necessary Redis rejects startup without Local fallback. An ordinary failed/late claim skips its point; healthy instances that have not lost a lease may try future points. Failed/late renewal or validity exhaustion closes every new admission in that Worker, cancels pending claims, requests cooperative Abort and shuts down/replaces it. Reconnection cannot revive eligibility."}),"\n",(0,n.jsx)(t.p,{children:"Redis server time validates the schedule window. Replicas keep clocks synchronized; skew is diagnostic and never automatically corrected. Recovery considers only future points; cancellation cannot forcibly stop arbitrary business work or undo effects."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.a,{id:"vext-job-008"})}),"\n",(0,n.jsxs)(t.h3,{id:"vext-job-008-must-feature-scope",children:[(0,n.jsx)(t.a,{className:"rp-header-anchor","aria-hidden":"true",href:"#vext-job-008-must-feature-scope",children:"#"}),"VEXT-JOB-008 [MUST] Feature scope"]}),"\n",(0,n.jsx)(t.p,{children:"Jobs provides application-started Cron tasks, without interval, queues, payload enqueueing, priority, automatic retry, downtime catch-up, immediate startup execution, run-now, execution history storage, independent Worker Threads or an administration panel. Unknown fields cannot enable them."}),"\n",(0,n.jsx)(t.p,{children:"Reliable delivery, progress and history belong in a separate queue or business storage/monitoring. The framework promises neither business Exactly Once nor persistent coordination across independent Masters."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.a,{id:"vext-job-009"})}),"\n",(0,n.jsxs)(t.h3,{id:"vext-job-009-must-shutdown-and-side-effects",children:[(0,n.jsx)(t.a,{className:"rp-header-anchor","aria-hidden":"true",href:"#vext-job-009-must-shutdown-and-side-effects",children:"#"}),"VEXT-JOB-009 [MUST] Shutdown and side effects"]}),"\n",(0,n.jsx)(t.p,{children:"Shutdown closes new triggers/admissions, requests cancellation, waits within the entire application's shutdown.timeout budget, then cleans coordinator and dependencies. This setting uses seconds, not a separate wait per Job. Repeated close creates no new work. Uncooperative functions cannot be interrupted and completed effects cannot be rolled back."}),"\n",(0,n.jsx)(t.p,{children:"Rolling replacement validates the candidate first; mismatch rejects replacement while keeping the old Worker. Old admissions close before a replacement is activated. With IPC, drain/disconnect does not prove the handler stopped: only exact settlement or confirmed process exit releases its in-flight ownership, while consumed points remain. Master channel loss closes admissions, cancels and shuts down without Local fallback. IPC state is not persistent across a new Master."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.a,{id:"vext-job-010"})}),"\n",(0,n.jsxs)(t.h3,{id:"vext-job-010-must-testing-and-development",children:[(0,n.jsx)(t.a,{className:"rp-header-anchor","aria-hidden":"true",href:"#vext-job-010-must-testing-and-development",children:"#"}),"VEXT-JOB-010 [MUST] Testing and development"]}),"\n",(0,n.jsx)(t.p,{children:"Ordinary createTestApp neither scans nor runs project Jobs. createTestJobScheduler prepares supplied definitions and a controlled clock before necessary onReady. Only tick drives it; no discovery, real timers or mandatory Redis are needed for Local scheduling tests."}),"\n",(0,n.jsx)(t.p,{children:"Development runs Jobs by default. Task files or loaded dependencies cause cold restart after old scheduler closure, including custom directories; a development profile can disable tasks. The helper cannot replace real Master/Worker, Redis, crash and rolling tests."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.a,{id:"vext-job-011"})}),"\n",(0,n.jsxs)(t.h3,{id:"vext-job-011-must-discovery-and-documentation-selection",children:[(0,n.jsx)(t.a,{className:"rp-header-anchor","aria-hidden":"true",href:"#vext-job-011-must-discovery-and-documentation-selection",children:"#"}),"VEXT-JOB-011 [MUST] Discovery and documentation selection"]}),"\n",(0,n.jsx)(t.p,{children:"Default recursive selection includes ts/js/mjs/cjs/mts/cts, ignoring underscore filenames, declarations and test/spec files; underscore directories remain allowed. include replaces matching, exclude adds to built-in ignores, and actual extensions are not rewritten for production. Directories stay inside project boundaries."}),"\n",(0,n.jsx)(t.p,{children:"Each selected file contains one finite default SDK Job. Ordinary helpers/types/constants, dynamic fields, recognizable default aliases, CommonJS module.exports and bounded project-source default re-exports are allowed. Factories/conditional defaults, extra SDK declarations including unused positions, Job-valued named aliases, user getters/Proxies and later export mutations are rejected. Explicit name wins, otherwise derive the relative path without changing camelCase; disabled definitions also check duplicates. Builds validate before optimization and production need not carry src. Task module top level must not run business work or create independent timers; finite declaration validation is not a general side-effect sandbox."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.a,{id:"vext-job-012"})}),"\n",(0,n.jsxs)(t.h3,{id:"vext-job-012-must-static-evidence-and-project-state",children:[(0,n.jsx)(t.a,{className:"rp-header-anchor","aria-hidden":"true",href:"#vext-job-012-must-static-evidence-and-project-state",children:"#"}),"VEXT-JOB-012 [MUST] Static evidence and project state"]}),"\n",(0,n.jsx)(t.p,{children:"With project Docs enabled, the Jobs source defaults on and inherits jobs.dir/include/exclude individually. Explicit openapi.docs.code.jobs fields affect only documentation selection; disabling that source does not stop tasks, and disabled definitions may appear."}),"\n",(0,n.jsx)(t.p,{children:"Static scanning does not execute user config, task modules, getters or handlers to resolve dynamic values. Unknown/partial evidence retains reasons; inferred labels never substitute for unknown actual names. MCP Recipes generate explicit Cron, one default Job per file, with per-task TTL. Static checks identify expected coordination but runtimeVerified:false proves neither readiness, connectivity nor execution. Chinese, English, API, Recipe and capability descriptions must agree."})]})}function r(){let e=arguments.length>0&&void 0!==arguments[0]?arguments[0]:{},{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(a,{...e})}):a(e)}r.__RSPRESS_PAGE_META={},r.__RSPRESS_PAGE_META["en%2Fspecification%2Fjobs.md"]={toc:[{id:"vext-job-001-must-application-startup",text:"VEXT-JOB-001 [MUST] Application startup",depth:3},{id:"vext-job-002-must-schedule-definitions",text:"VEXT-JOB-002 [MUST] Schedule definitions",depth:3},{id:"vext-job-003-must-execution-and-overlap",text:"VEXT-JOB-003 [MUST] Execution and overlap",depth:3},{id:"vext-job-004-must-replica-configuration",text:"VEXT-JOB-004 [MUST] Replica configuration",depth:3},{id:"vext-job-005-must-trigger-deduplication",text:"VEXT-JOB-005 [MUST] Trigger deduplication",depth:3},{id:"vext-job-006-must-running-leases",text:"VEXT-JOB-006 [MUST] Running leases",depth:3},{id:"vext-job-007-must-redis-failures",text:"VEXT-JOB-007 [MUST] Redis failures",depth:3},{id:"vext-job-008-must-feature-scope",text:"VEXT-JOB-008 [MUST] Feature scope",depth:3},{id:"vext-job-009-must-shutdown-and-side-effects",text:"VEXT-JOB-009 [MUST] Shutdown and side effects",depth:3},{id:"vext-job-010-must-testing-and-development",text:"VEXT-JOB-010 [MUST] Testing and development",depth:3},{id:"vext-job-011-must-discovery-and-documentation-selection",text:"VEXT-JOB-011 [MUST] Discovery and documentation selection",depth:3},{id:"vext-job-012-must-static-evidence-and-project-state",text:"VEXT-JOB-012 [MUST] Static evidence and project state",depth:3}],title:"Scheduled Jobs contract",headingTitle:"Scheduled Jobs contract",frontmatter:{}},s.d(t,{default:()=>r})}}]);